import{_ as a,C as i,o as n,c as o,E as s,a2 as r}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"More Admission Checks Do Not Mean Safer Admission","description":"","frontmatter":{"title":"More Admission Checks Do Not Mean Safer Admission","date":"2026-09-14","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"在多执行通道的智能体系统中，准入必须证明哪些与所选通道相关的事实，才能避免无关依赖成为错误门禁，同时不把技术可用性误当成业务授权？","summary":"A provider-valid API-key lane was rejected because the host lacked a CLI needed only by another lane. Correct admission is a proof bundle bound to the selected execution lane, its verifier, and evidence freshness; business authorization remains separate.","sources":["research/analysis/Q-20260914-01-lane-bound-admission-proof.md"],"item_id":"Q-20260914-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-14-more-checks-not-safer-admission-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-09-14-more-checks-not-safer-admission.md","filePath":"en/digital-employee/2026-09-14-more-checks-not-safer-admission.md","lastUpdated":1789388081000}'),c={name:"en/digital-employee/2026-09-14-more-checks-not-safer-admission.md"};function l(d,e,h,u,p,m){const t=i("ArticleCover");return n(),o("div",null,[s(t,{image:"/assets/covers/daily-2026-09-14-more-checks-not-safer-admission-cover.png",kicker:"Digital Employee · Daily Research",title:"More Admission Checks Do Not Mean Safer Admission",summary:"A provider-valid API-key lane was rejected because the host lacked a CLI needed only by another lane. Correct admission is a proof bundle bound to the selected execution lane, its verifier, and evidence freshness; business authorization remains separate.",version:"Q-20260914-01",status:"Daily Runtime V5 · 2026-09-14",languageHref:"/zh/digital-employee/2026-09-14-more-checks-not-safer-admission",languageLabel:"中文"}),e[0]||(e[0]=r('<h1 id="more-admission-checks-do-not-mean-safer-admission" tabindex="-1">More Admission Checks Do Not Mean Safer Admission <a class="header-anchor" href="#more-admission-checks-do-not-mean-safer-admission" aria-label="Permalink to &quot;More Admission Checks Do Not Mean Safer Admission&quot;">​</a></h1><p>An agent is configured on a clean machine with an API key. The provider accepts the credential and live validation succeeds, yet the first-agent flow still fails because the runtime requires a local CLI probe used only by a different subscription lane.</p><p>This is not merely a missing dependency. A requirement from an unused route has become an authority gate for the selected route. <strong>An admission check is correct only when its meaning matches the execution lane that will actually be used. More checks do not automatically create safer admission.</strong></p><h2 id="when-a-valid-credential-still-cannot-enter" tabindex="-1">When a Valid Credential Still Cannot Enter <a class="header-anchor" href="#when-a-valid-credential-still-cannot-enter" aria-label="Permalink to &quot;When a Valid Credential Still Cannot Enter&quot;">​</a></h2><p>The same-date Research Object examines a clean-machine failure and merged correction in Paperclip. The direct API-key lane had already passed the relevant provider check, but the old flow continued into a local subscription CLI hello probe. Because the clean host did not contain that CLI, the valid route was denied.</p><p>The correction resolves connection mode first. The API-key lane re-verifies the key at the provider boundary and no longer consults the local CLI. Subscription execution retains the CLI hello requirement. Release smoke uses a narrow HTTPS provider mock that serves the expected model-list request and returns 404 for unexpected paths.</p><p>The source reports 26 of 26 environment-route tests passing, 42 of 42 connection and compatibility tests passing, and a clean TypeScript check. These results support the bounded mechanism. They are not the same fact as an end-to-end clean-machine pass in the next published canary containing the fix.</p><h2 id="the-lane-determines-the-proof" tabindex="-1">The Lane Determines the Proof <a class="header-anchor" href="#the-lane-determines-the-proof" aria-label="Permalink to &quot;The Lane Determines the Proof&quot;">​</a></h2><p>A product may expose several execution routes, but the facts required by those routes differ.</p><p>A direct API route needs evidence about the credential, provider and endpoint. A subscription CLI route needs evidence that the host contains the binary, the local session is valid and the environment can launch it. A hybrid lane may need both remote credential truth and local capability.</p><p>Admission rules should therefore be derived from the route selected for this execution, not from the union of everything the product supports. A universal superset appears conservative, but it grants irrelevant facts the power to reject a valid route.</p><p>The opposite error matters too. Lane-specific admission must not mean weaker admission. It should remove irrelevant proofs while strengthening relevant ones. In the bounded fix, the API-key lane replaces an unrelated host probe with provider re-verification; it does not simply skip verification.</p><h2 id="four-facts-cannot-be-one-boolean" tabindex="-1">Four Facts Cannot Be One Boolean <a class="header-anchor" href="#four-facts-cannot-be-one-boolean" aria-label="Permalink to &quot;Four Facts Cannot Be One Boolean&quot;">​</a></h2><p>At least four evidence identities should remain separate:</p><ul><li><strong>credential validity</strong> — whether a specific provider accepts the credential;</li><li><strong>host capability</strong> — whether this machine satisfies the selected lane&#39;s local requirements;</li><li><strong>execution-lane identity</strong> — which concrete route the system will use;</li><li><strong>business authorization</strong> — whether this agent may create the intended business effect now.</li></ul><p>They answer different questions. A valid credential does not prove that a local tool can run. A capable host does not prove that a session is valid. Even when the first three facts hold, they do not authorize a customer message, production mutation or charge.</p><p>A single <code>admission=true</code> erases those distinctions. When admission fails, an auditor cannot tell which requirement applied, who verified it or when the evidence became stale.</p><h2 id="an-auditable-admission-proof-bundle" tabindex="-1">An Auditable Admission Proof Bundle <a class="header-anchor" href="#an-auditable-admission-proof-bundle" aria-label="Permalink to &quot;An Auditable Admission Proof Bundle&quot;">​</a></h2><p>A stronger design makes the route selector produce a versioned proof bundle. It records:</p><ul><li>a stable lane identity and contract version;</li><li>the facts required by that lane;</li><li>the authoritative verifier for each fact;</li><li>evidence values or digests, collection times and freshness windows;</li><li>negative applicability—requirements that explicitly do not govern this lane;</li><li>provider, credential, host and environment identities;</li><li>an unambiguous binding from the admitted bundle to the route actually executed;</li><li>separate action-time business-authorization evidence.</li></ul><p>If execution changes lanes, the old bundle is invalid. If credentials, host capability or provider state can change, stale evidence must be re-read. Cacheability is not permanence.</p><p>The point is not more logging. It is preserving why each fact applied. That explanation makes accidental cross-lane reuse inspectable.</p><h2 id="why-more-checks-can-be-dangerous" tabindex="-1">Why More Checks Can Be Dangerous <a class="header-anchor" href="#why-more-checks-can-be-dangerous" aria-label="Permalink to &quot;Why More Checks Can Be Dangerous&quot;">​</a></h2><p>Universal preflight is often framed as conservative: if the runtime asks for a superset, it cannot miss a dependency. Safety, however, comes from semantic fit rather than check count.</p><p>An unused dependency creates two risks. First, false denial prevents a legitimate worker from using a valid route. Second, false authority encourages operators to treat one host capability as proof that the entire execution path is ready, even when the credential and provider actually used were never verified.</p><p>Lane-specific contracts add configuration cost. If the requirement mapping is duplicated across call sites, drift can become worse than one conservative gate. The remedy is a canonical lane-to-requirement registry with positive, negative and route-switch tests—not scattered exceptions.</p><h2 id="technical-usability-is-not-business-authority" tabindex="-1">Technical Usability Is Not Business Authority <a class="header-anchor" href="#technical-usability-is-not-business-authority" aria-label="Permalink to &quot;Technical Usability Is Not Business Authority&quot;">​</a></h2><p>Provider acceptance proves that a credential works at that provider boundary. A host probe proves that a runtime condition exists. Neither fact grants organizational permission for the next business action.</p><p>High-impact calls still need current authorization: task ownership, target and scope, policy state, human approval where required, and authoritative external preconditions. Technical admission asks, “Can this route work?” Business authorization asks, “May this effect occur now?”</p><p>Keeping them separate also prevents permission inheritance. A long-lived digital employee may reuse a technical environment, but it should not inherit a new destination or effect merely because yesterday&#39;s preflight passed.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>The evidence comes from one product and one clean-machine path. It does not define a universal schema for providers, enterprise federation or hybrid lanes, and it does not establish one freshness window for every fact.</p><p>The bounded rule is nevertheless clear: <strong>admission must prove the facts the selected route actually depends on and bind those proofs to the route used. Unrelated dependencies must not own denial, and technical usability must not own business authorization.</strong></p><p>Open questions remain: how hybrid lanes combine remote and local proof; how a long task migrates when a lane contract changes; how the runtime attests that the admitted route was the executed route; and which actions require human approval after technical admission.</p><p><strong>Evidence and source:</strong></p><ul><li><a href="https://github.com/paperclipai/paperclip/pull/13372" target="_blank" rel="noreferrer">Paperclip PR #13372: lane-specific admission correction</a>, merged engineering evidence, 2026.</li></ul>',36))])}const v=a(c,[["render",l]]);export{b as __pageData,v as default};
